        <footer className=\"page-footer\"><span>© 2026 Пульс</span><span>Больше ясности. Больше возможностей.</span><span className=\"footer-version\">Аналитика с заботой о деталях<Icon name=\"pulse\" size={15}/></span></footer>
      </main>
    </div>
    <div className=\"sr-only\" role=\"status\" aria-live=\"polite\">{exported ? 'Данные экспортированы в CSV' : ''}</div>
  </div>;
}
EOF"

